sql.where:
r.deleted = 0



    AND r.river_id = #{reqVO.riverId}


    AND r.name LIKE CONCAT('%', #{reqVO.name}, '%')


    AND r.responsibility_section LIKE CONCAT('%', #{reqVO.responsibilitySection}, '%')


    AND r.area_code = #{reqVO.areaCode}



    AND r.manager_id = #{reqVO.managerId}


    AND r.operation_status_id = #{reqVO.operationStatusId}



    AND r.cleaning_type_id = #{reqVO.cleaningTypeId}


    AND r.water_cleaning_frequency LIKE CONCAT('%', #{reqVO.waterCleaningFrequency}, '%')


    AND r.cleaning_time LIKE CONCAT('%', #{reqVO.cleaningTime}, '%')




    AND r.staff_ids LIKE CONCAT('%', #{reqVO.staffIds}, '%')


    AND r.tool_ids LIKE CONCAT('%', #{reqVO.toolIds}, '%')



    AND r.waste_fishing_estimate = #{reqVO.wasteFishingEstimate}


    AND r.monitor_type_id = #{reqVO.monitorTypeId}


    AND r.water_quality_cycle LIKE CONCAT('%', #{reqVO.waterQualityCycle}, '%')




    AND r.monitor_indicators LIKE CONCAT('%', #{reqVO.monitorIndicators}, '%')



    AND r.monitor_by = #{reqVO.monitorBy}




    AND r.plan_monitor_time BETWEEN #{reqVO.planMonitorTime[0]} AND #{reqVO.planMonitorTime[1]}



    AND r.monitor_status_id = #{reqVO.monitorStatusId}




    AND r.last_monitor_time BETWEEN #{reqVO.lastMonitorTime[0]} AND #{reqVO.lastMonitorTime[1]}




    AND r.next_monitor_remind_time BETWEEN #{reqVO.nextMonitorRemindTime[0]} AND #{reqVO.nextMonitorRemindTime[1]}



    AND r.monitor_data_qualified_rate = #{reqVO.monitorDataQualifiedRate}


    AND r.warning_count = #{reqVO.warningCount}


    AND r.problem_type_id = #{reqVO.problemTypeId}


    AND r.problem_location LIKE CONCAT('%', #{reqVO.problemLocation}, '%')


    AND r.problem_desc LIKE CONCAT('%', #{reqVO.problemDesc}, '%')


    AND r.report_by = #{reqVO.reportBy}




    AND r.report_time BETWEEN #{reqVO.reportTime[0]} AND #{reqVO.reportTime[1]}




    AND r.problem_media_url LIKE CONCAT('%', #{reqVO.problemMediaUrl}, '%')



    AND r.dept_id = #{reqVO.deptId}


    AND r.handle_by = #{reqVO.handleBy}




    AND r.dispatch_time BETWEEN #{reqVO.dispatchTime[0]} AND #{reqVO.dispatchTime[1]}



    AND r.handle_status_id = #{reqVO.handleStatusId}


    AND r.is_timeout = #{reqVO.isTimeout}




    AND r.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

mapper.select:
SELECT r.*, a.area_name AS area_name, u1.user_name AS manager_name, os.name AS operation_status_name, ct.cleaning_name AS cleaning_type_name, mt.monitor_name AS monitor_type_name, u2.user_name AS monitor_name, mst.monitor_status_name AS monitor_status_name, pt.name AS problem_type_name, u3.user_name AS report_name, d.name AS dept_name, u4.user_name AS handle_name, hs.name AS handle_status_name, tt.name AS task_type_name, IFNULL(GROUP_CONCAT(DISTINCT u5.user_name), '') AS staffs_name_str, IFNULL(GROUP_CONCAT(DISTINCT t.name), '') AS tools_name_str FROM river r LEFT JOIN sys_area a ON r.area_code = a.area_code AND a.deleted = 0 LEFT JOIN sys_user u1 ON r.manager_id = u1.user_id AND u1.deleted = 0 LEFT JOIN sys_operation_status os ON r.operation_status_id = os.sys_operation_status_id AND os.deleted = 0 LEFT JOIN sys_cleaning_type ct ON r.cleaning_type_id = ct.cleaning_type_id AND ct.deleted = 0 LEFT JOIN sys_monitor_type mt ON r.monitor_type_id = mt.monitor_type_id AND mt.deleted = 0 LEFT JOIN sys_monitor_status mst ON r.monitor_status_id = mst.monitor_status_id AND mst.deleted = 0 LEFT JOIN sys_problem_type pt ON r.problem_type_id = pt.sys_problem_type_id AND pt.deleted = 0 LEFT JOIN sys_handle_status hs ON r.handle_status_id = hs.sys_handle_status_id AND hs.deleted = 0 LEFT JOIN sys_task_type tt ON r.task_type_id = tt.sys_task_type_id AND tt.deleted = 0 LEFT JOIN sys_dept d ON r.dept_id = d.sys_dept_id AND d.deleted = 0 LEFT JOIN sys_user u2 ON r.monitor_by = u2.user_id AND u2.deleted = 0 LEFT JOIN sys_user u3 ON r.report_by = u3.user_id AND u3.deleted = 0 LEFT JOIN sys_user u4 ON r.handle_by = u4.user_id AND u4.deleted = 0 -- 处理负责人员JSON解析 LEFT JOIN sys_user u5 ON FIND_IN_SET( u5.user_id, REPLACE(REPLACE(REPLACE(REPLACE(r.staff_ids, '[', ''), ']', ''), '"', ''), ' ', '') ) AND u5.deleted = 0 -- 处理保洁工具JSON解析 LEFT JOIN sys_tool t ON FIND_IN_SET( t.sys_tool_id, REPLACE(REPLACE(REPLACE(REPLACE(r.tool_ids, '[', ''), ']', ''), '"', ''), ' ', '') ) AND t.deleted = 0
GROUP BY r.id, a.area_name, u1.user_name, os.name, ct.cleaning_name, mt.monitor_name, u2.user_name, mst.monitor_status_name, pt.name, u3.user_name, d.name, u4.user_name, hs.name, tt.name
ORDER BY r.id DESC LIMIT #{reqVO.offset}, #{reqVO.pageSize}
